use tokio::sync::mpsc;

#[tokio::main]
async fn main() {
    let (sender, mut receiver) = mpsc::channel(33);
    for value in 1..257 {
        sender.send(value).await.unwrap();
        receiver.recv().await.unwrap();
        assert!(receiver.is_empty(), "bounded {value}. len: {}", receiver.len());
    }
    let (sender, mut receiver) = mpsc::unbounded_channel();
    for value in 1..257 {
        sender.send(value).unwrap();
        assert_eq!(receiver.recv().await.unwrap(), value);
        assert!(receiver.is_empty(), "unbounded {value}. len: {}", receiver.len());
    }
    println!("OK");
}
EOF
